#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void l2_norm_kernel(const half* input, half* output, int batch_size, int dim) {
    int batch_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (batch_idx >= batch_size) return;

    // Shared memory for reduction
    extern __shared__ half sdata[];

    // Compute squared sum for this batch element
    half sum = __float2half(0.0f);
    const half* input_row = input + batch_idx * dim;
    half* output_row = output + batch_idx * dim;

    // Process 4 elements at a time for better memory coalescing
    for (int i = 0; i < dim; i += 4) {
        half4 vals = reinterpret_cast<const half4&>(input_row[i]);
        sum = __hadd(sum, __hadd(__hmul(vals.x, vals.x), __hadd(__hmul(vals.y, vals.y), 
                __hadd(__hmul(vals.z, vals.z), __hmul(vals.w, vals.w)))));
    }

    // Handle remaining elements
    for (int i = (dim / 4) * 4; i < dim; i++) {
        half val = input_row[i];
        sum = __hadd(sum, __hmul(val, val));
    }

    // Reduce within block
    int tid = threadIdx.x;
    sdata[tid] = sum;
    __syncthreads();

    // Perform tree reduction
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] = __hadd(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }

    // Get the final sum for this batch element
    half norm = sdata[0];

    // Compute sqrt of sum (norm)
    half inv_norm = __hdiv(__float2half(1.0f), __hsqrt(norm));

    // Normalize the row
    for (int i = 0; i < dim; i++) {
        output_row[i] = __hmul(input_row[i], inv_norm);
    }
}

void launch_l2_norm(const half* input, half* output, int batch_size, int dim) {
    const int block_size = 256;
    const int grid_size = (batch_size + block_size - 1) / block_size;

    size_t shared_mem_size = block_size * sizeof(half);

    l2_norm_kernel<<<grid_size, block_size, shared_mem_size>>>(
        input, output, batch_size, dim);
}
